import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Limitación de Velocidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/advanced/ratelimit.md","filePath":"es/advanced/ratelimit.md","lastUpdated":1784903584000}'),t={name:"es/advanced/ratelimit.md"};function o(r,e,l,d,p,c){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="limitacion-de-velocidad" tabindex="-1">Limitación de Velocidad <a class="header-anchor" href="#limitacion-de-velocidad" aria-label="Permalink to &quot;Limitación de Velocidad&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>swag2mcp tiene un limitador de velocidad incorporado que evita que el LLM llame al mismo endpoint de API con demasiada frecuencia. Esto protege contra llamadas duplicadas accidentales y respeta los límites de velocidad de la API.</p><h2 id="como-funciona" tabindex="-1">Cómo funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to &quot;Cómo funciona&quot;">​</a></h2><p>Cada endpoint tiene un período de enfriamiento. Si el LLM intenta llamar al mismo endpoint nuevamente dentro del período de enfriamiento, la llamada se rechaza con un error estructurado.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(endpoint) → se ejecuta</span></span>
<span class="line"><span>t=2s  → invoke(endpoint) → rechazado con error rate_limit</span></span>
<span class="line"><span>t=12s → invoke(endpoint) → se ejecuta (el enfriamiento ha pasado)</span></span></code></pre></div><h3 id="comportamiento-predeterminado" tabindex="-1">Comportamiento predeterminado <a class="header-anchor" href="#comportamiento-predeterminado" aria-label="Permalink to &quot;Comportamiento predeterminado&quot;">​</a></h3><ul><li><strong>Enfriamiento:</strong> 10 segundos por endpoint</li><li><strong>Alcance:</strong> Por endpoint — llamar al endpoint A no afecta al endpoint B</li><li><strong>Respuesta de error:</strong> El LLM recibe un <code>LLMError</code> con código <code>rate_limit</code> y un mensaje que indica cuánto tiempo esperar</li><li><strong>Restablecimiento:</strong> Después de 10 segundos de inactividad en ese endpoint</li></ul><h3 id="formato-de-error" tabindex="-1">Formato de error <a class="header-anchor" href="#formato-de-error" aria-label="Permalink to &quot;Formato de error&quot;">​</a></h3><p>Cuando se limita la velocidad, el LLM recibe:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;límite de velocidad excedido para el endpoint </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: intente de nuevo en 8 segundos&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Espere a que expire el período de enfriamiento, luego intente invocar el endpoint nuevamente. Use la herramienta de búsqueda para encontrar otros endpoints que pueda llamar mientras tanto.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>El LLM puede usar esta información para esperar y reintentar, o cambiar a un endpoint diferente.</p><h3 id="por-que-existe" tabindex="-1">Por qué existe <a class="header-anchor" href="#por-que-existe" aria-label="Permalink to &quot;Por qué existe&quot;">​</a></h3><ul><li><strong>Evita llamadas duplicadas accidentales</strong> — el LLM podría llamar al mismo endpoint múltiples veces en rápida sucesión</li><li><strong>Protege contra los límites de velocidad de la API</strong> — muchas APIs tienen sus propios límites de velocidad, y alcanzarlos causaría errores</li><li><strong>Ahorra recursos</strong> — reduce el tráfico de red innecesario</li></ul><h2 id="configuracion" tabindex="-1">Configuración <a class="header-anchor" href="#configuracion" aria-label="Permalink to &quot;Configuración&quot;">​</a></h2><p>Puede deshabilitar el limitador de velocidad o cambiar el intervalo de enfriamiento:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Deshabilitar el limitador de velocidad por completo</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Intervalo de enfriamiento personalizado</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>Tipo:</strong> <code>bool</code></li><li><strong>Valor predeterminado:</strong> <code>false</code></li><li><strong>Efecto:</strong> Cuando es <code>true</code>, el limitador de velocidad por endpoint está deshabilitado. El LLM puede llamar al mismo endpoint repetidamente sin esperar.</li><li><strong>Cuándo habilitar:</strong> Pruebas, depuración, o cuando necesita llamar al mismo endpoint múltiples veces en rápida sucesión.</li><li><strong>Cuándo mantenerlo deshabilitado (recomendado):</strong> Producción. El limitador de velocidad evita el abuso accidental.</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>Tipo:</strong> duración (formato Go: <code>10s</code>, <code>30s</code>, <code>1m</code>)</li><li><strong>Valor predeterminado:</strong> <code>10s</code></li><li><strong>Efecto:</strong> Establece el período de enfriamiento entre llamadas al mismo endpoint.</li><li><strong>Cuándo aumentar:</strong> APIs con límites de velocidad estrictos (por ejemplo, 10 solicitudes por minuto).</li><li><strong>Cuándo disminuir:</strong> APIs internas donde usted controla la carga.</li><li><strong>Ejemplos:</strong> <code>5s</code>, <code>30s</code>, <code>1m</code>, <code>2m</code></li></ul><h2 id="notas-importantes" tabindex="-1">Notas importantes <a class="header-anchor" href="#notas-importantes" aria-label="Permalink to &quot;Notas importantes&quot;">​</a></h2><ul><li><strong>Seguimiento por endpoint</strong> — cada endpoint se rastrea de forma independiente. Llamar a un endpoint no afecta a los demás.</li><li><strong>Error devuelto al LLM</strong> — la segunda llamada dentro del enfriamiento se rechaza con un error <code>rate_limit</code>. El LLM recibe la duración del enfriamiento y puede reintentar después de esperar.</li><li><strong>No se necesita limpieza</strong> — el limitador de velocidad rastrea los endpoints automáticamente y no requiere mantenimiento.</li></ul>`,23)])])}const u=a(t,[["render",o]]);export{m as __pageData,u as default};
